import{_ as o}from"./chunks/vscode-heal.B4mhIb6w.js";import{_ as i,C as s,o as r,c as n,j as t,a as d,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse('{"title":"Editor extensions","description":"Piwi in VS Code and the JetBrains IDEs: tests recorded at the cursor, the latest CI failures at their failing lines with your local runs laid over them and the heal as a quick fix, the tests behind each locator, file and line, brittle locators, and the locators an unsaved change breaks.","frontmatter":{"title":"Editor extensions","description":"Piwi in VS Code and the JetBrains IDEs: tests recorded at the cursor, the latest CI failures at their failing lines with your local runs laid over them and the heal as a quick fix, the tests behind each locator, file and line, brittle locators, and the locators an unsaved change breaks.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editors.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editors.html"}],["meta",{"property":"og:title","content":"Editor extensions | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Piwi in VS Code and the JetBrains IDEs: tests recorded at the cursor, the latest CI failures at their failing lines with your local runs laid over them and the heal as a quick fix, the tests behind each locator, file and line, brittle locators, and the locators an unsaved change breaks."}]]},"headers":[],"relativePath":"features/editors.md","filePath":"features/editors.md","lastUpdated":1795813550000}'),c={name:"features/editors.md"};function p(u,e,f,g,m,w){const a=s("Needs");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"editor-extensions",tabindex:"-1"},[d("Editor extensions "),t("a",{class:"header-anchor",href:"#editor-extensions","aria-label":'Permalink to "Editor extensions"'},"​")],-1)),h(a,{editor:""}),e[1]||(e[1]=l('<p>The Piwi extension for VS Code (and Cursor, VSCodium) and the Piwi plugin for the JetBrains IDEs with the LSP API (WebStorm, IntelliJ IDEA Ultimate, Rider, from 2024.1) bring what the dashboard knows about your suite to the line you are editing. Both run the same editor service; the <a href="./jetbrains.html">JetBrains plugin</a> page lists what the plugin needs and draws differently.</p><figure><img src="'+o+'" alt="VS Code: a CI failure at its line, the heal offered as a quick fix"><figcaption>The latest run&#39;s failure at its line, and the heal as a quick fix.</figcaption></figure><h2 id="install-and-connect" tabindex="-1">Install and connect <a class="header-anchor" href="#install-and-connect" aria-label="Permalink to &quot;Install and connect&quot;">​</a></h2><p><strong>You need a Piwi instance:</strong> the <a href="/features/desktop.html">desktop app</a>, <code>npx @piwitests/server</code> or the Docker image. Recording, running a test by its line, and pausing and stepping through it need none. Piwi reads Playwright Test suites in JavaScript and TypeScript.</p><p>Install <strong>Piwi</strong> from the <strong><a href="https://marketplace.visualstudio.com/items?itemName=PiwiTests.piwi" target="_blank" rel="noreferrer">Visual Studio Marketplace ↗</a></strong> (<code>piwitests.piwi</code> in the extensions view) or the <strong><a href="https://plugins.jetbrains.com/plugin/34674-piwi" target="_blank" rel="noreferrer">JetBrains Marketplace ↗</a></strong> (<strong>Settings → Plugins</strong>). It starts on a trusted workspace holding a Playwright config, and reads the connection the reporter already uses: the <code>PIWI_*</code> variables in the environment or the workspace <code>.env</code>, or the <a href="/features/desktop.html">desktop app</a>. Otherwise, run <strong>Piwi: Connect…</strong> (<strong>Settings → Tools → Piwi</strong> in a JetBrains IDE) and sign in with the browser: <a href="./editor-connection.html">Editor connection</a> has the steps.</p><p>The first workspace with a Playwright config opens the first steps: VS Code&#39;s <strong>Get started with Piwi</strong> walkthrough once per machine (unless <code>workbench.welcomePage.walkthroughs.openOnInstall</code> is off), a JetBrains IDE&#39;s <strong>Get started</strong> tab once per installation (<a href="./jetbrains.html#install-and-start">JetBrains plugin</a>). <strong>Piwi: Get started</strong> opens them again. The desktop app and MCP offers follow one at a time: one per window in VS Code, per IDE session in a JetBrains IDE. VS Code 1.101 and later lists the MCP server itself.</p><p>In VS Code, the extension also opens a path clicked in the dashboard: <a href="./ide-integration.html#vs-code-the-piwi-extension">Open in editor</a>.</p><p>Self-hosted, zero telemetry. No file of your workspace is sent to the instance: the project&#39;s <a href="/guide/concepts.html#locator-index">locator index</a>, <a href="/features/code-reach.html">code reach</a> and latest run are compared with your files locally.</p><h2 id="ci-failures-in-the-problems-panel" tabindex="-1">CI failures in the Problems panel <a class="header-anchor" href="#ci-failures-in-the-problems-panel" aria-label="Permalink to &quot;CI failures in the Problems panel&quot;">​</a></h2><p>The failures of the latest complete <a href="/reference/test-metadata.html#run-origin">CI run</a> on the checked-out branch, else the default branch, are in the Problems panel at the line that failed, with your local runs laid over them, and each failing line follows your edits until a run covers its test again. The heal, the trace, a rerun and the fix plan are quick fixes on the failure, and the failures view lists them as a tree: <a href="./editor-failures.html">Failures in the editor</a>.</p><h2 id="the-tests-behind-each-line" tabindex="-1">The tests behind each line <a class="header-anchor" href="#the-tests-behind-each-line" aria-label="Permalink to &quot;The tests behind each line&quot;">​</a></h2><p>Lines above the code (CodeLens):</p><table tabindex="0"><thead><tr><th>File</th><th>What it shows</th><th>Click</th></tr></thead><tbody><tr><td>A spec</td><td>the tests Piwi knows in it; beside each <code>test(…)</code>, its latest result in the gutter, a failing test&#39;s body tinted, and on hover that result&#39;s run, the pass rate, <a href="/features/flaky-tests.html">flaky</a> score and root cause, quarantine and selections</td><td>runs those tests</td></tr><tr><td>A page object or spec</td><td>above each locator line (in a spec, unless its only test is the one around it), the tests using it, their actions, and how many fail or flake</td><td>runs those tests</td></tr><tr><td>An application file</td><td>the tests that reach it, from <a href="/features/code-reach.html">code reach</a>; with <a href="./editor-coverage.html">coverage</a>, each function&#39;s too</td><td>runs those tests</td></tr><tr><td>A page file (Nuxt <code>pages/**</code>)</td><td>the tests acting on that page, its locators and how many are brittle</td><td>runs those tests</td></tr></tbody></table><p>Above a flaky test: Flake Lab&#39;s <strong>flaky N%</strong> and <a href="./flake-lab.html#from-the-editor-and-the-failure-pages">top suspect</a>, then <strong>Reproduce this flake</strong> and, once reproduced, <strong>Verify the flake fix</strong>, which run <code>piwi flake</code>; beside a team instance, <strong>Reproduce this flake in the desktop app</strong>.</p><h2 id="timeouts" tabindex="-1">Timeouts <a class="header-anchor" href="#timeouts" aria-label="Permalink to &quot;Timeouts&quot;">​</a></h2><p>A test whose <code>test.slow()</code> is no longer needed, or whose timeout is far above its p95, gets a note and a quick fix: remove <code>test.slow()</code>, or set <code>test.setTimeout</code> to the suggested value.</p><h2 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h2><ul><li>After a page and a <code>.</code> in a spec or a page object: the locator chains your suite already uses on the pages this file&#39;s tests visit, most used first and brittle ones last. The page is <code>page</code>, <code>this.page</code>, or any page the code at the cursor can use, the same ones <a href="/features/editor-recording.html#start-a-recording">a recording</a> offers: another page fixture of the test (<code>adminPage.</code>), a page object&#39;s page field (<code>this.root.</code>), a page the test opens (<code>newPage()</code>, a popup).</li><li>Right after <code>expect(</code>: the same chains on the page in use there, such as <code>page.getByRole(&#39;button&#39;, { name: &#39;Pay&#39; })</code>, so an assertion&#39;s locator is written in one step.</li><li>At the start of a statement: the <a href="/features/test-functions.html">functions</a> of your catalog whose URL pattern matches those pages, as a call with a placeholder per parameter.</li><li>In a <code>piwi:</code> annotation: the types (<code>piwi:owner</code>, <code>piwi:priority</code>, <code>piwi:feature</code>, <code>piwi:link</code>), then the owners, priorities or features they take; in <code>tag: [&#39;@…&#39;]</code>, the tags your tests already use.</li></ul><h2 id="brittle-locators" tabindex="-1">Brittle locators <a class="header-anchor" href="#brittle-locators" aria-label="Permalink to &quot;Brittle locators&quot;">​</a></h2><p>A locator the <a href="/reference/locator-stability.html">stability rules</a> rate brittle is a warning on its line; one worth a look is a hint. When the capture fixtures stored a stable alternative for that call site on its last passing run, the quick fix replaces the chain with it.</p><h2 id="the-locators-a-change-breaks" tabindex="-1">The locators a change breaks <a class="header-anchor" href="#the-locators-a-change-breaks" aria-label="Permalink to &quot;The locators a change breaks&quot;">​</a></h2><p>In an application file, the unsaved buffer is compared with <code>HEAD</code> as you type, as <a href="/features/preflight.html"><code>piwi preflight</code></a> compares a diff. A changed line whose string a locator finds its element by is a warning, with the chains it breaks on hover, and one quick fix that rewrites every call site.</p><h2 id="piwi-s-mcp-server-for-the-agent" tabindex="-1">Piwi&#39;s MCP server for the agent <a class="header-anchor" href="#piwi-s-mcp-server-for-the-agent" aria-label="Permalink to &quot;Piwi&#39;s MCP server for the agent&quot;">​</a></h2><p>In VS Code 1.101 and later, the extension provides Piwi&#39;s <a href="/features/mcp.html">MCP server</a> to the editor&#39;s agent with the connection it already has. Elsewhere, <strong>Piwi: Copy the MCP server configuration</strong> puts an entry on the clipboard: VS Code&#39;s <code>mcp.json</code> or Cursor&#39;s <code>mcpServers</code>, as you choose; in a JetBrains IDE, an <code>mcpServers</code> entry running <code>mcp-remote</code>, for your agent&#39;s MCP settings (the AI Assistant&#39;s, when it is installed and enabled). It holds your API key: keep it out of the repository.</p><p>The key carries your whole role, write tools included. For a token of the agent&#39;s own, set <code>piwi.mcpAuthorization</code> to <code>sign-in</code> (<strong>Settings → Tools → Piwi → Agents (MCP)</strong> in a JetBrains IDE): the server comes without a key, and the agent <a href="/features/mcp.html#authentication">signs in</a> in your browser when it first connects. You revoke that token with your API keys. The desktop app keeps its own token. For the runs the editor starts: <a href="./agent-run-control.html">Run control for agents</a>.</p><h2 id="colors-and-hidden-messages" tabindex="-1">Colors and hidden messages <a class="header-anchor" href="#colors-and-hidden-messages" aria-label="Permalink to &quot;Colors and hidden messages&quot;">​</a></h2><p>VS Code&#39;s theme colors, set in <code>workbench.colorCustomizations</code>: <code>piwi.failingTestBackground</code> and <code>piwi.failingLineBackground</code> tint a failing test and the line it failed at, <code>piwi.failingTestOverviewRuler</code> and <code>piwi.failingLineOverviewRuler</code> mark them in the scrollbar; <code>piwi.flakyForeground</code> colors the word flaky after a flaky test&#39;s line in the Testing view; <code>piwi.recordingBlockBackground</code> and <code>piwi.recordingBlockOverviewRuler</code> mark the block a recording writes; <code>piwi.executionPointBackground</code> and <code>piwi.executionPointOverviewRuler</code> the line a test is stopped at, <code>piwi.failurePointBackground</code> and <code>piwi.failurePointOverviewRuler</code> the line it holds a failure at. The coverage marks have <a href="./editor-coverage.html#the-marks">their own</a>. A JetBrains IDE has the failing test, its line, the lines being recorded and the stopped line under <strong>Settings → Editor → Color Scheme → Piwi</strong>.</p><p><strong>Don&#39;t Show Again</strong> on a message that may come again adds its kind to VS Code&#39;s <code>piwi.hiddenMessages</code> (<a href="/reference/editor-settings.html#advanced">Editor settings</a> lists the kinds); remove a kind to see its message again.</p><p>VS Code&#39;s Piwi settings come in five groups, Connection, Runs, In the editor, Agents (MCP) and Advanced, as JetBrains&#39; settings page does: <a href="/reference/editor-settings.html">Editor settings</a> lists each one, what the editor shows among them. Your own choices (how runs start and notify, breakpoints, the status bar&#39;s alert, the agent&#39;s sign-in) hold in every workspace: a repository&#39;s <code>.vscode/settings.json</code> sets only the instance and the project, the failure severity, serving runs to agents and Piwi&#39;s tests in the Testing view. A JetBrains IDE keeps the same choices in its own settings, for every project, and the failure severity and serving runs to agents for each project.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>Each extension&#39;s commands, under <strong>Piwi:</strong> in VS Code&#39;s command palette and <strong>Tools → Piwi</strong> in a JetBrains IDE, are listed with what they do on <a href="/reference/editor-commands.html">Editor commands</a>. Both editors bind <code>Ctrl+Shift+Alt+K</code> to run the test at the cursor, <code>Ctrl+Shift+Alt+F</code> to re-run the failing tests, <code>Ctrl+Shift+Alt+R</code> to record at the cursor and stop the recording, and <code>Ctrl+Shift+Alt+B</code> to open the failures, in a JavaScript or TypeScript file or Piwi&#39;s views; <code>Cmd</code> for <code>Ctrl</code> on macOS. Some JetBrains keymaps, macOS&#39;s among them, take other letters: <a href="/reference/editor-commands.html#keys">Keys</a>. <strong>Preferences: Open Keyboard Shortcuts</strong> changes them in VS Code (search <code>piwi</code>), <strong>Settings → Keymap</strong> in a JetBrains IDE (search <code>Piwi</code>).</p><h2 id="jetbrains-ides" tabindex="-1">JetBrains IDEs <a class="header-anchor" href="#jetbrains-ides" aria-label="Permalink to &quot;JetBrains IDEs&quot;">​</a></h2><p>The plugin runs with the project&#39;s Node.js interpreter, 20 or later, and shows the failures in the Piwi tool window, the lines above the code with Code Vision, and its actions under <strong>Tools → Piwi</strong>: <a href="./jetbrains.html">JetBrains plugin</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-failures.html">Failures in the editor</a>: the CI failures, their quick fixes and the failures view.</li><li><a href="./editor-runs.html">Runs from the editor</a>: run tests, and follow them in <a href="./editor-status-bar.html">the status bar</a>.</li><li><a href="./editor-recording.html">Record tests from the editor</a>: steps written at the cursor as you take them.</li><li><a href="./write-run-fix.html">Write, run and fix a test</a>: the loop across tools.</li></ul>',35))])}const v=i(c,[["render",p]]);export{y as __pageData,v as default};
